{"content":""""Find the cheapest grouping of books, with prices in cents."""

from collections import Counter
from functools import lru_cache
from itertools import combinations


# Index by the number of distinct titles in a discounted group.
_GROUP_PRICES = (0, 800, 1520, 2160, 2560, 3000)


def total(basket):
    """Return the minimum price in cents for an iterable of book titles."""
    counts = tuple(sorted(Counter(basket).values(), reverse=True))

    @lru_cache(maxsize=None)
    def cheapest(remaining):
        if not remaining:
            return 0
        if len(remaining) == 1:
            return remaining[0] * _GROUP_PRICES[1]

        best = sum(remaining) * _GROUP_PRICES[1]
        seen = set()
        for size in range(1, len(remaining) + 1):
            for group in combinations(range(len(remaining)), size):
                next_counts = list(remaining)
                for index in group:
                    next_counts[index] -= 1
                state = tuple(sorted(
                    (count for count in next_counts if count), reverse=True
                ))
                # Title identities do not affect discounts. Equivalent states
                # need only be considered once, even for different groups.
                if state in seen:
                    continue
                seen.add(state)
                best = min(best, _GROUP_PRICES[size] + cheapest(state))
        return best

    return cheapest(counts)
