{"content":"import unittest

from book_store import total


class BookStoreTest(unittest.TestCase):
    def test_empty_basket(self):
        self.assertEqual(total([]), 0)

    def test_distinct_title_discounts(self):
        for size, expected in enumerate((0, 800, 1520, 2160, 2560, 3000)):
            with self.subTest(size=size):
                self.assertEqual(total(list(range(1, size + 1))), expected)

    def test_identical_books_have_no_discount(self):
        self.assertEqual(total([1] * 10), 8000)

    def test_duplicate_book_outside_discounted_set(self):
        self.assertEqual(total([1, 1, 2, 3]), 2960)

    def test_two_groups_of_four_beat_five_and_three(self):
        self.assertEqual(total([1, 1, 2, 2, 3, 3, 4, 5]), 5120)

    def test_multiple_rebalanced_groups(self):
        self.assertEqual(total([1, 1, 2, 2, 3, 3, 4, 5] * 2), 10240)

    def test_large_mixed_basket(self):
        basket = [1] * 5 + [2] * 5 + [3] * 4 + [4] * 5 + [5] * 4
        self.assertEqual(total(basket), 14120)

    def test_order_and_title_identity_do_not_change_price(self):
        self.assertEqual(total([5, 4, 3, 5, 2, 4, 1, 3]), 5120)

    def test_basket_is_not_modified(self):
        basket = [3, 1, 2, 1]
        original = basket.copy()
        total(basket)
        self.assertEqual(basket, original)

    def test_accepts_an_iterator(self):
        self.assertEqual(total(iter([1, 2, 3, 4, 5])), 3000)


if __name__ == "__main__":
    unittest.main()
